_num VARCHAR, div3_airport VARCHAR, div3_airport_id VARCHAR, div3_airport_seq_id VARCHAR, div3_wheels_on VARCHAR, div3_total_g_time VARCHAR, div3_longest_g_time VARCHAR, div3_wheels_off VARCHAR, div3_tail_num VARCHAR, div4_airport VARCHAR, div4_airport_id VARCHAR, div4_airport_seq_id VARCHAR, div4_wheels_on VARCHAR, div4_total_g_time VARCHAR, div4_longest_g_time VARCHAR, div4_wheels_off VARCHAR, div4_tail_num VARCHAR, div5_airport VARCHAR, div5_airport_id VARCHAR, div5_airport_seq_id VARCHAR, div5_wheels_on VARCHAR, div5_total_g_time VARCHAR, div5_longest_g_time VARCHAR, div5_wheels_off VARCHAR, div5_tail_num VARCHAR, _source_id VARCHAR, _period VARCHAR, _vintage_id VARCHAR);
