CREATE MACRO norm_county (x) AS (regexp_replace("replace"(regexp_replace(regexp_replace(upper(COALESCE(x, '')), ' (COUNTY|PARISH|BOROUGH|CENSUS AREA|MUNICIPALITY|CITY AND BOROUGH|CITY AND COUNTY|MUNICIPIO|\(INDEPENDENT CITY\))$', ''), ' CITY$', ''), 'SAINT ', 'ST '), '[^A-Z]', '', 'g'));
CREATE VIEW v_county_econ_annual AS SELECT geofips AS county_fips, "year", max("value") FILTER (WHERE (line_code = 2)) AS population, (max("value") FILTER (WHERE (line_code = 1)) * 1000) AS personal_income_usd, max("value") FILTER (WHERE (line_code = 3)) AS per_capita_income_usd, string_agg(DISTINCT value_flag, ',') FILTER (WHERE (value_flag IS NOT NULL)) AS suppression_flags FROM bea_county_income WHERE ("right"(geofips, 3) != '000') GROUP BY ALL;
CREATE VIEW v_county_econ_mapped AS SELECT m.county_fips, m.bea_fips, m.via_combination, e."year", e.population, e.personal_income_usd, e.per_capita_income_usd, e.suppression_flags FROM (county_bea_area AS m INNER JOIN v_county_econ_annual AS e ON ((e.county_fips = m.bea_fips)));
CREATE VIEW v_ontime_flight AS SELECT f.*, (TRY_CAST(substr(lpad(CAST(f.crs_dep_time AS VARCHAR), 4, '0'), 1, 2) AS INTEGER) % 24) AS crs_dep_hour, (TRY_CAST(substr(lpad(CAST(f.crs_arr_time AS VARCHAR), 4, '0'), 1, 2) AS INTEGER) % 24) AS crs_arr_hour, make_date(CAST(f."year" AS INTEGER), CAST(f."month" AS INTEGER), 1) AS period_month FROM ontime_flight AS f;
CREATE VIEW v_source_freshness AS WITH sel AS (SELECT source_id, max(period) AS latest_period, count_star() AS periods_loaded, min(period) AS first_period FROM ingest_manifest WHERE selected GROUP BY 1), exp AS (SELECT c.id AS source_id, c.period_kind, c.cadence, c.expected_lag_days, (current_date - (c.expected_lag_days * to_days(CAST(trunc(CAST(1 AS DOUBLE)) AS INTEGER)))) AS horizon FROM source_catalog AS c) SELECT e.source_id, e.period_kind, e.cadence, s.first_period, s.latest_period, s.periods_loaded, CASE  WHEN ((e.period_kind = 'month')) THEN (strftime((e.horizon - to_months(CAST(trunc(CAST(1 AS DOUBLE)) AS INTEGER))), '%Y-%m')) WHEN ((e.period_kind = 'year')) THEN (CAST(("year"(e.horizon) - 1) AS VARCHAR)) WHEN ((e.period_kind = 'version')) THEN (NULL) WHEN ((e.period_kind = 'snapshot')) THEN (NULL) ELSE NULL END AS expected_latest_period, CASE  WHEN ((s.latest_period IS NULL)) THEN ('MISSING') WHEN (((e.period_kind = 'month') AND (s.latest_period < strftime((e.horizon - to_months(CAST(trunc(CAST(2 AS DOUBLE)) AS INTEGER))), '%Y-%m')))) THEN ('STALE') WHEN (((e.period_kind = 'year') AND (s.latest_period < CAST(("year"(e.horizon) - 1) AS VARCHAR)))) THEN ('STALE') WHEN (((e.period_kind = 'snapshot') AND (TRY_CAST(s.latest_period AS DATE) < (current_date - to_days(CAST(trunc(CAST(120 AS DOUBLE)) AS INTEGER)))))) THEN ('STALE') ELSE 'OK' END AS freshness FROM (exp AS e LEFT JOIN sel AS s USING (source_id));
CREATE VIEW v_source_period_status AS WITH loaded AS (SELECT source_id, period FROM ingest_manifest WHERE selected GROUP BY ALL), cat AS (SELECT id AS source_id, period_kind, period_basis, expected_lag_days FROM source_catalog WHERE (period_kind IN ('month', 'year'))), bounds AS (SELECT c.source_id, c.period_kind, c.period_basis, min(l.period) AS first_period, max(l.period) AS last_loaded, (current_date - (c.expected_lag_days * to_days(CAST(trunc(CAST(1 AS DOUBLE)) AS INTEGER)))) AS horizon FROM (cat AS c INNER JOIN loaded AS l USING (source_id)) GROUP BY ALL), spine AS ((SELECT b.source_id, b.period_kind, strftime(m, '%Y-%m') AS period, (m <= (b.horizon - to_months(CAST(trunc(CAST(1 AS DOUBLE)) AS INTEGER)))) AS expected FROM bounds AS b , generate_series(CAST((b.first_period || '-01') AS DATE), greatest(CAST((b.last_loaded || '-01') AS DATE), CAST(date_trunc('month', current_date) AS DATE)), to_months(CAST(trunc(CAST(1 AS DOUBLE)) AS INTEGER))) AS g(m) WHERE (b.period_kind = 'month')) UNION ALL (SELECT b.source_id, b.period_kind, CAST(y AS VARCHAR), CASE  WHEN ((b.period_basis = 'fiscal')) THEN ((make_date(y, 9, 30) <= b.horizon)) ELSE (y <= ("year"(b.horizon) - 1)) END FROM bounds AS b , generate_series(CAST(b.first_period AS INTEGER), greatest(CAST(b.last_loaded AS INTEGER), "year"(current_date))) AS g(y) WHERE (b.period_kind = 'year'))) SELECT s.source_id, s.period_kind, s.period, CASE  WHEN ((l.period IS NOT NULL)) THEN ('loaded') WHEN (s.expected) THEN ('missing') ELSE 'not_yet_expected' END AS status FROM (spine AS s LEFT JOIN loaded AS l ON (((l.source_id = s.source_id) AND (l.period = s.period))));
CREATE VIEW v_t100_segment AS SELECT t.*, make_date(CAST(t."year" AS INTEGER), CAST(t."month" AS INTEGER), 1) AS period_month, cfg.description AS aircraft_config_desc, CASE  WHEN ((t.aircraft_config = 1)) THEN ('passenger') WHEN ((t.aircraft_config = 2)) THEN ('freight') WHEN ((t.aircraft_config = 3)) THEN ('combi') WHEN ((t.aircraft_config = 4)) THEN ('seaplane') ELSE 'other' END AS service_type, cls.description AS class_desc, (t."class" IN ('F', 'G')) AS is_scheduled, ((t.origin_country != 'US') OR (t.dest_country != 'US')) AS is_international FROM ((t100_segment AS t LEFT JOIN bts_lookup AS cfg ON (((cfg.lookup = 'L_AIRCRAFT_CONFIG') AND (cfg.code = CAST(t.aircraft_config AS VARCHAR))))) LEFT JOIN bts_lookup AS cls ON (((cls.lookup = 'L_SERVICE_CLASS') AND (cls.code = t."class")))) WHERE (t.origin != t.dest);
CREATE VIEW xref_faa_lid AS WITH cand AS ((SELECT faa_lid AS lid, airport_id, current_code, 1 AS prio FROM dim_airport WHERE (faa_lid IS NOT NULL)) UNION ALL (SELECT unnest(all_codes), airport_id, current_code, 2 FROM dim_airport WHERE (country = 'US'))) SELECT lid AS faa_lid, airport_id, current_code, CASE  WHEN ((prio = 1)) THEN ('faa_lid') ELSE 'bts_code_history' END AS match_rule FROM (cand LEFT JOIN (SELECT origin_airport_id AS airport_id, (sum(passengers) + sum(departures_performed)) AS t FROM t100_segment GROUP BY 1) AS tr USING (airport_id)) QUALIFY (row_number() OVER (PARTITION BY lid ORDER BY prio, COALESCE(tr.t, 0) DESC, airport_id) = 1);
CREATE VIEW v_airport_month_activity AS WITH "months" AS (SELECT source_id, period, CAST((period || '-01') AS DATE) AS "month", status FROM v_source_period_status WHERE (source_id IN ('bts_t100_segment', 'bts_ontime', 'faa_atads_ops'))), t100 AS (SELECT origin_airport_id AS airport_id, _period AS period, sum(departures_performed) AS deps, sum(passengers) AS pax FROM t100_segment WHERE (origin != dest) GROUP BY ALL), ot AS (SELECT origin_airport_id AS airport_id, _period AS period, count_star() FILTER (WHERE (cancelled = 0)) AS deps, CAST(NULL AS DOUBLE) AS pax FROM ontime_flight GROUP BY ALL), atads AS (SELECT x.airport_id, a._period AS period, sum(a.total_operations) AS deps, CAST(NULL AS DOUBLE) AS pax FROM (atads_airport_ops AS a INNER JOIN xref_faa_lid AS x ON ((x.faa_lid = a.locid))) GROUP BY ALL) SELECT d.airport_id, d.current_code, m.source_id, m."month", m.status AS source_month_status, CASE  WHEN ((m.source_id = 'faa_atads_ops')) THEN ('tower_operations') ELSE 'departures' END AS activity_measure, CASE  WHEN ((m.status = 'loaded')) THEN (COALESCE(x.deps, 0)) ELSE NULL END AS activity, CASE  WHEN (((m.status = 'loaded') AND (m.source_id = 'bts_t100_segment'))) THEN (COALESCE(x.pax, 0)) ELSE NULL END AS passengers FROM ((dim_airport AS d CROSS JOIN "months" AS m) LEFT JOIN ((SELECT 'bts_t100_segment' AS source_id, * FROM t100) UNION ALL (SELECT 'bts_ontime', * FROM ot)UNION ALL (SELECT 'faa_atads_ops', * FROM atads)) AS x ON (((x.airport_id = d.airport_id) AND (x.period = m.period) AND (x.source_id = m.source_id)))) WHERE ((d.country = 'US') AND ((m.source_id != 'faa_atads_ops') OR (d.airport_id = ANY(SELECT x.airport_id FROM (atads_airport_ops AS a INNER JOIN xref_faa_lid AS x ON ((x.faa_lid = a.locid)))))));
CREATE VIEW v_atads_airport_ops AS SELECT a.*, make_date(a."year", a."month", 1) AS period_month, CASE  WHEN ((a."month" >= 10)) THEN ((a."year" + 1)) ELSE a."year" END AS fiscal_year, x.airport_id, x.current_code AS bts_code FROM (atads_airport_ops AS a LEFT JOIN xref_faa_lid AS x ON ((x.faa_lid = a.locid)));
CREATE VIEW v_cbsa_econ_annual AS WITH yrs AS (SELECT DISTINCT "year" FROM bea_county_income), mem AS (SELECT cb.cbsa_code, cb.cbsa_title, cb.metro_micro, cb.county_fips, m.bea_fips FROM (cbsa_county AS cb LEFT JOIN county_bea_area AS m ON ((m.county_fips = cb.county_fips)))), areas AS (SELECT DISTINCT mem.cbsa_code, y."year", mem.bea_fips FROM mem , yrs AS y WHERE (mem.bea_fips IS NOT NULL)), agg AS (SELECT a.cbsa_code, a."year", sum(e.population) AS population, sum(e.personal_income_usd) AS personal_income_usd FROM (areas AS a LEFT JOIN v_county_econ_annual AS e ON (((e.county_fips = a.bea_fips) AND (e."year" = a."year")))) GROUP BY 1, 2), miss AS (SELECT mem.cbsa_code, y."year", count_star() AS counties, count_star() FILTER (WHERE (e.population IS NULL)) AS counties_missing_population FROM ((mem CROSS JOIN yrs AS y) LEFT JOIN v_county_econ_annual AS e ON (((e.county_fips = mem.bea_fips) AND (e."year" = y."year")))) GROUP BY 1, 2) SELECT m.cbsa_code, t.cbsa_title, t.metro_micro, m."year", CASE  WHEN ((m.counties_missing_population = 0)) THEN (g.population) ELSE NULL END AS population, CASE  WHEN ((m.counties_missing_population = 0)) THEN (g.personal_income_usd) ELSE NULL END AS personal_income_usd, CASE  WHEN ((m.counties_missing_population = 0)) THEN ((g.personal_income_usd / "nullif"(g.population, 0))) ELSE NULL END AS per_capita_income_usd, m.counties, m.counties_missing_population, g.population AS population_partial_if_missing FROM ((miss AS m INNER JOIN (SELECT cbsa_code, min(cbsa_title) AS cbsa_title, min(metro_micro) AS metro_micro FROM cbsa_county GROUP BY 1) AS t USING (cbsa_code)) LEFT JOIN agg AS g ON (((g.cbsa_code = m.cbsa_code) AND (g."year" = m."year"))));
CREATE VIEW v_faa_cargo_annual AS WITH longf AS ((SELECT locid, st, cy, value_cy AS landed_weight_lbs, 'own_workbook' AS basis, cy AS workbook_cy FROM faa_cargo) UNION ALL (SELECT locid, st, (cy - 1), value_prior_cy, 'next_workbook_prior_column', cy FROM faa_cargo)) SELECT e.* EXCLUDE (current_code, rk), e.current_code AS bts_code FROM (SELECT l.*, x.airport_id, x.current_code, row_number() OVER (PARTITION BY COALESCE(CAST(x.airport_id AS VARCHAR), ('LID:' || l.locid)), l.cy ORDER BY l.workbook_cy DESC, l.locid) AS rk FROM (longf AS l LEFT JOIN xref_faa_lid AS x ON ((x.faa_lid = l.locid))) WHERE (l.landed_weight_lbs IS NOT NULL)) AS e WHERE (rk = 1);
CREATE VIEW v_faa_enplanements_annual AS WITH longf AS ((SELECT locid, st, hub, cy, value_cy AS enplanements, 'own_workbook' AS basis, cy AS workbook_cy, _vintage_id FROM faa_enplanements) UNION ALL (SELECT locid, st, hub, (cy - 1), value_prior_cy, 'next_workbook_prior_column', cy, _vintage_id FROM faa_enplanements)) SELECT e.* EXCLUDE (current_code, rk), e.current_code AS bts_code FROM (SELECT l.*, x.airport_id, x.current_code, row_number() OVER (PARTITION BY COALESCE(CAST(x.airport_id AS VARCHAR), ('LID:' || l.locid)), l.cy ORDER BY l.workbook_cy DESC, l.locid) AS rk FROM (longf AS l LEFT JOIN xref_faa_lid AS x ON ((x.faa_lid = l.locid))) WHERE (l.enplanements IS NOT NULL)) AS e WHERE (rk = 1);
CREATE VIEW v_faa_grant AS SELECT g.*, x.airport_id, x.current_code AS bts_code FROM (faa_grant AS g LEFT JOIN xref_faa_lid AS x ON ((x.faa_lid = g.locid)));
CREATE VIEW v_taf_enplanements AS SELECT e.*, CASE  WHEN ((e.scenario = 0)) THEN ('historical') WHEN ((e.scenario = 1)) THEN ('forecast') ELSE NULL END AS record_type, CAST(e._period AS INTEGER) AS taf_release_year, x.airport_id, x.current_code AS bts_code, ((e.aac + e.aat) + e.commuter) AS domestic_enplanements, (e.us_flag + e.frgn_flag) AS international_enplanements, ((((COALESCE(e.aac, 0) + COALESCE(e.aat, 0)) + COALESCE(e.commuter, 0)) + COALESCE(e.us_flag, 0)) + COALESCE(e.frgn_flag, 0)) AS total_enplanements FROM (taf_enplanements AS e LEFT JOIN xref_faa_lid AS x ON ((x.faa_lid = e.locid)));
CREATE VIEW v_taf_operations AS SELECT o.*, CASE  WHEN ((o.scenario = 0)) THEN ('historical') WHEN ((o.scenario = 1)) THEN ('forecast') ELSE NULL END AS record_type, CAST(o._period AS INTEGER) AS taf_release_year, x.airport_id, x.current_code AS bts_code, (((((COALESCE(o.itn_ac, 0) + COALESCE(o.itn_at, 0)) + COALESCE(o.itn_ga, 0)) + COALESCE(o.itn_mil, 0)) + COALESCE(o.loc_ga, 0)) + COALESCE(o.loc_mil, 0)) AS total_ops FROM (taf_operations AS o LEFT JOIN xref_faa_lid AS x ON ((x.faa_lid = o.locid)));
CREATE VIEW v_airport_area_econ AS SELECT x.airport_id, d.current_code, x.county_fips, x.cbsa_code, x.cbsa_title, x.metro_micro, x.match_rule, c."year", c.population AS county_population, c.personal_income_usd AS county_personal_income_usd, m.population AS cbsa_population, m.personal_income_usd AS cbsa_personal_income_usd, m.per_capita_income_usd AS cbsa_per_capita_income_usd FROM (((xref_airport_county AS x INNER JOIN dim_airport AS d USING (airport_id)) LEFT JOIN v_county_econ_mapped AS c ON ((c.county_fips = x.county_fips))) LEFT JOIN v_cbsa_econ_annual AS m ON (((m.cbsa_code = x.cbsa_code) AND (m."year" = c."year"))));
CREATE VIEW v_airport_investment_records AS (SELECT 'faa_grant' AS record_type, CASE  WHEN ((g.award_date IS NULL)) THEN ('announced') ELSE 'awarded' END AS status, g.airport_id, g.locid, g.fiscal_year, g.award_date AS record_date, g.total_amount AS amount_usd, g.project_summary AS description, g.grant_number AS record_key, 'faa_grants' AS source_id, g._vintage_id FROM v_faa_grant AS g) UNION ALL (SELECT 'npias_development_estimate', 'planned_need_estimate', x.airport_id, n.locid, NULL, NULL, n.development_estimate, (((('NPIAS ' || n.npias_cycle) || ' 5-year AIP-eligible development estimate (role: ') || COALESCE(n."role", n.hub, '?')) || ')'), ((n.locid || ':') || n.npias_cycle), 'faa_npias', n._vintage_id FROM (npias_airport AS n LEFT JOIN xref_faa_lid AS x ON ((x.faa_lid = n.locid))))UNION ALL (SELECT 'npias_new_airport_estimate', 'planned_need_estimate', NULL, n.locid, NULL, NULL, n.development_estimate, (('NPIAS ' || n.npias_cycle) || ' proposed new/replacement airport'), ((n.locid || ':') || n.npias_cycle), 'faa_npias', n._vintage_id FROM npias_new_airport AS n)UNION ALL (SELECT 'curated_project', c.status, x.airport_id, c.airport_iata, NULL, TRY_CAST(c.effective_from AS DATE), NULL, (c.item || COALESCE((((' — ' || c."value") || ' ') || c.unit), '')), ((c.airport_iata || ':') || c.item), 'curated_constraints', c._vintage_id FROM (curated_constraint AS c LEFT JOIN (SELECT DISTINCT airport_id, unnest(all_codes) AS code FROM dim_airport WHERE (country = 'US')) AS x ON ((x.code = c.airport_iata))) WHERE (c.category IN ('terminal_project', 'runway_project', 'master_plan')));
